export const faqCopy: Record<Locale, FaqCopy> = {
  en: { back: "Back to planner", title: "Help & FAQ", subtitle: "Clear answers to what matters before you set off.", search: "Search FAQ...", empty: "No matching questions. Try another search.", categories: [{ title: "Tolls & Vignettes", questions: [{ question: "How are toll rates calculated?", answer: "We calculate tolls using official rates, vehicle category, road distance and seasonal variations." }, { question: "Where do I buy official vignettes?", answer: "We link directly to the official government issuers in each country to avoid unnecessary fees and markups." }, { question: "What applies to environmental stickers such as Crit'Air?", answer: "Some European cities require their own environmental stickers. We show which zones may require one on your route." }] }, { title: "EV & Ultra-fast Charging", questions: [{ question: "Which charging networks are covered?", answer: "We cover major open European networks including Ionity, Tesla Supercharger open stations, Fastned, EnBW and more." }, { question: "How often is charging data updated?", answer: "The charging database is regularly synchronized with live status and open databases." }, { question: "How is consumption estimated with a roof box or load?", answer: "The calculator automatically adds a safety buffer and adjusts for terrain and increased aerodynamic drag." }] }, { title: "Accuracy & Data", questions: [{ question: "Where does the route data come from?", answer: "Route and map data come from OpenStreetMap and OSRM." }, { question: "Are these figures estimates or guaranteed prices?", answer: "They're estimates — clear, rule-based calculations from open data, not a guarantee. Prices at official portals can change, so we always link you straight to them before you buy." }] }, { title: "Your Account", questions: [{ question: "Can I use AutoVere without an account?", answer: "Yes — the route planner, cost calculations and vignette checklist work fully without signing in. An account is only for saving trips, vehicles and places, and for Pro or Business features." }, { question: "What does creating an account actually give me?", answer: "A place to save your trips, vehicles and favourite stops so they're there next time — plus, on Pro or Business, live charger data, weather-adjusted charging plans and vehicle profiles." }] }, { title: "Privacy", questions: [{ question: "Does AutoVere store my routes?", answer: "Only if you're signed in and choose to save a trip. Calculations you run without an account stay on your device." }, { question: "Is my personal data sold to third parties?", answer: "No. We don't sell data or use third-party ad tracking, and we're fully GDPR-compliant. See our Privacy Policy for the full detail." }] }] },
  de: { back: "Zurück zum Routenplaner", title: "Hilfe & FAQ", subtitle: "Direkte Antworten auf die wichtigsten Fragen vor der Abfahrt.", search: "FAQ durchsuchen...", empty: "Keine passenden Fragen gefunden.", categories: [{ title: "Maut & Vignetten", questions: [{ question: "Wie werden Mautgebühren berechnet?", answer: "Wir berechnen Maut anhand offizieller Tarife, Fahrzeugklasse, Streckenlänge und saisonaler Unterschiede." }, { question: "Wo kaufe ich offizielle Vignetten?", answer: "Wir verlinken direkt zu den offiziellen staatlichen Ausstellern, damit keine unnötigen Gebühren oder Aufschläge entstehen." }, { question: "Was gilt für Umweltplaketten wie Crit'Air?", answer: "Einige europäische Städte verlangen eigene Umweltplaketten. Wir zeigen, in welchen Zonen auf Ihrer Route eine solche Plakette erforderlich sein kann." }] }, { title: "E-Auto & Schnellladen", questions: [{ question: "Welche Ladenetzwerke werden abgedeckt?", answer: "Wir decken große offene europäische Netzwerke wie Ionity, offene Tesla-Supercharger, Fastned, EnBW und weitere ab." }, { question: "Wie oft werden die Ladedaten aktualisiert?", answer: "Die Ladedatenbank wird regelmäßig mit Live-Status und offenen Datenbanken synchronisiert." }, { question: "Wie wird der Verbrauch mit Dachbox oder Ladung berechnet?", answer: "Der Rechner ergänzt automatisch eine Sicherheitsmarge und berücksichtigt Gelände sowie erhöhten Luftwiderstand." }] }, { title: "Genauigkeit & Daten", questions: [{ question: "Woher stammen die Routendaten?", answer: "Routen- und Kartendaten stammen von OpenStreetMap und OSRM." }, { question: "Sind das Schätzungen oder garantierte Preise?", answer: "Es sind Schätzungen — klare, regelbasierte Berechnungen aus offenen Daten, keine Garantie. Preise auf offiziellen Portalen können sich ändern, deshalb verlinken wir dich vor dem Kauf immer direkt dorthin." }] }, { title: "Ihr Konto", questions: [{ question: "Kann ich AutoVere ohne Konto nutzen?", answer: "Ja — der Routenplaner, die Kostenberechnung und die Vignetten-Checkliste funktionieren vollständig ohne Anmeldung. Ein Konto brauchst du nur, um Reisen, Fahrzeuge und Orte zu speichern, sowie für Pro- oder Business-Funktionen." }, { question: "Was bringt mir ein Konto eigentlich?", answer: "Einen Ort, an dem deine Reisen, Fahrzeuge und Lieblingsstopps gespeichert bleiben — plus, bei Pro oder Business, Live-Ladedaten, wetterangepasste Ladepläne und Fahrzeugprofile." }] }, { title: "Datenschutz", questions: [{ question: "Speichert AutoVere meine Routen?", answer: "Nur, wenn du angemeldet bist und eine Reise speicherst. Berechnungen ohne Konto bleiben auf deinem Gerät." }, { question: "Werden meine persönlichen Daten an Dritte verkauft?", answer: "Nein. Wir verkaufen keine Daten und nutzen kein Tracking durch Drittanbieter-Werbung, und wir sind vollständig DSGVO-konform. Alle Details findest du in unserer Datenschutzerklärung." }] }] },
  no: { back: "Tilbake til ruteplanleggeren", title: "Hjelp og ofte stilte spørsmål (FAQ)", subtitle: "Klare svar på det viktigste før bilferien.", search: "Søk i spørsmål...", empty: "Fant ingen spørsmål som passer.", categories: [{ title: "Bompenger og vignetter", questions: [{ question: "Hvordan beregnes bomtakster?", answer: "Vi beregner bompenger basert på offisielle takster, kjøretøykategori, veistrekning og sesongvariasjoner." }, { question: "Hvor kjøper jeg offisielle vignetter?", answer: "Vi lenker kun direkte til de statlige og offisielle utstederne i hvert enkelt land for å unngå unødvendige gebyrer og påslag." }, { question: "Hva gjelder for miljømerker som Crit'Air?", answer: "Ulike europeiske byer krever egne miljømerker. Vi viser hvilke soner som krever oblater på din rute." }] }, { title: "Elbil og lynlading", questions: [{ question: "Hvilke ladenettverk dekkes?", answer: "Alle store åpne europeiske nettverk som Ionity, Tesla Supercharger (åpne stasjoner), Fastned, EnBW med flere." }, { question: "Hvor ofte oppdateres ladedata?", answer: "Ladedatabasen synkroniseres jevnlig med sanntidsstatus og åpne databaser." }, { question: "Hvordan beregnes forbruk med takboks eller last?", answer: "Kalkulatoren legger automatisk til en sikkerhetsbuffer på 75 % og justerer for topografi og økt luftmotstand." }] }, { title: "Nøyaktighet og data", questions: [{ question: "Hvor kommer rutedataene fra?", answer: "Rute- og kartdata hentes fra OpenStreetMap og OSRM." }, { question: "Er dette estimater eller garanterte priser?", answer: "Det er estimater — klare, regelbaserte beregninger fra åpne data, ikke en garanti. Priser på offisielle portaler kan endre seg, så vi lenker deg alltid rett dit før du kjøper." }] }, { title: "Din konto", questions: [{ question: "Kan jeg bruke AutoVere uten konto?", answer: "Ja — ruteplanleggeren, kostnadsberegningene og vignett-sjekklisten fungerer helt uten innlogging. En konto trenger du bare for å lagre reiser, kjøretøy og steder, samt for Pro- eller Bedrift-funksjoner." }, { question: "Hva får jeg egentlig ut av å opprette en konto?", answer: "Et sted der reisene, kjøretøyene og favorittstoppene dine blir liggende til neste gang — pluss, med Pro eller Bedrift, live ladedata, værjusterte ladeplaner og kjøretøyprofiler." }] }, { title: "Personvern", questions: [{ question: "Lagrer AutoVere rutene mine?", answer: "Bare hvis du er logget inn og velger å lagre en reise. Beregninger du gjør uten konto blir værende på din egen enhet." }, { question: "Blir persondataene mine solgt til tredjeparter?", answer: "Nei. Vi selger ikke data eller bruker tredjeparts annonsesporing, og vi er fullt GDPR-kompatible. Se personvernerklæringen vår for alle detaljer." }] }] },
  pl: { back: "Powrót do planera", title: "Pomoc i FAQ", subtitle: "Wszystko, co musisz wiedzieć przed wyruszeniem w trasę.", search: "Szukaj w FAQ...", empty: "Nie znaleziono pasujących pytań.", categories: [{ title: "Opłaty drogowe i winiety", questions: [{ question: "Jak obliczane są opłaty drogowe?", answer: "Obliczamy opłaty na podstawie oficjalnych stawek, kategorii pojazdu, długości trasy i zmian sezonowych." }, { question: "Gdzie kupić oficjalne winiety?", answer: "Linkujemy bezpośrednio do oficjalnych państwowych wystawców, aby uniknąć niepotrzebnych opłat i prowizji." }, { question: "Co dotyczy naklejek ekologicznych, takich jak Crit'Air?", answer: "Niektóre europejskie miasta wymagają własnych naklejek ekologicznych. Pokazujemy strefy, w których mogą być wymagane na trasie." }] }, { title: "Samochody elektryczne i ładowanie", questions: [{ question: "Które sieci ładowania są uwzględniane?", answer: "Obejmujemy główne otwarte sieci europejskie, takie jak Ionity, otwarte stacje Tesla Supercharger, Fastned, EnBW i inne." }, { question: "Jak często aktualizowane są dane ładowania?", answer: "Baza ładowania jest regularnie synchronizowana ze statusem na żywo i otwartymi bazami danych." }, { question: "Jak obliczane jest zużycie z boksem dachowym lub ładunkiem?", answer: "Kalkulator automatycznie dodaje margines bezpieczeństwa i uwzględnia ukształtowanie terenu oraz większy opór powietrza." }] }, { title: "Dane i dokładność", questions: [{ question: "Skąd pochodzą dane o trasach?", answer: "Dane tras i map pochodzą z OpenStreetMap i OSRM." }, { question: "Czy to szacunki, czy gwarantowane ceny?", answer: "To szacunki — przejrzyste, oparte na regułach obliczenia na podstawie otwartych danych, a nie gwarancja. Ceny na oficjalnych portalach mogą się zmieniać, dlatego zawsze kierujemy Cię tam bezpośrednio przed zakupem." }] }, { title: "Twoje konto", questions: [{ question: "Czy mogę korzystać z AutoVere bez konta?", answer: "Tak — planer trasy, obliczenia kosztów i lista winiet działają w pełni bez logowania. Konto potrzebne jest tylko do zapisywania podróży, pojazdów i miejsc oraz do funkcji Pro i Firma." }, { question: "Co właściwie daje mi założenie konta?", answer: "Miejsce, w którym Twoje podróże, pojazdy i ulubione przystanki zostaną zapisane na następny raz — a w planie Pro lub Firma dodatkowo dane ładowarek na żywo, plany ładowania uwzględniające pogodę i profile pojazdów." }] }, { title: "Prywatność", questions: [{ question: "Czy AutoVere zapisuje moje trasy?", answer: "Tylko jeśli jesteś zalogowany i zdecydujesz się zapisać podróż. Obliczenia wykonane bez konta pozostają na Twoim urządzeniu." }, { question: "Czy moje dane osobowe są sprzedawane stronom trzecim?", answer: "Nie. Nie sprzedajemy danych ani nie korzystamy ze śledzenia reklamowego stron trzecich, a nasza działalność jest w pełni zgodna z RODO. Pełne informacje znajdziesz w naszej Polityce Prywatności." }] }] },
  fr: { back: "Retour au planificateur", title: "Aide et FAQ", subtitle: "Des réponses claires aux questions essentielles avant votre départ.", search: "Rechercher dans la FAQ...", empty: "Aucune question correspondante.", categories: [{ title: "Péages et vignettes", questions: [{ question: "Comment les péages sont-ils calculés ?", answer: "Nous calculons les péages selon les tarifs officiels, la catégorie du véhicule, la distance et les variations saisonnières." }, { question: "Où acheter les vignettes officielles ?", answer: "Nous renvoyons directement vers les émetteurs officiels de chaque pays afin d'éviter les frais et majorations inutiles." }, { question: "Qu'en est-il des vignettes environnementales comme Crit'Air ?", answer: "Certaines villes européennes exigent leur propre vignette environnementale. Nous indiquons les zones susceptibles d'en demander une sur votre itinéraire." }] }, { title: "Recharge des véhicules électriques", questions: [{ question: "Quels réseaux de recharge sont couverts ?", answer: "Nous couvrons les grands réseaux européens ouverts comme Ionity, les stations Tesla Supercharger ouvertes, Fastned, EnBW et d'autres." }, { question: "À quelle fréquence les données de recharge sont-elles mises à jour ?", answer: "La base de recharge est régulièrement synchronisée avec les statuts en temps réel et les bases ouvertes." }, { question: "Comment la consommation est-elle estimée avec un coffre de toit ou une charge ?", answer: "Le calculateur ajoute automatiquement une marge de sécurité et tient compte du relief et de l'augmentation de la traînée aérodynamique." }] }, { title: "Données et précision", questions: [{ question: "D'où viennent les données d'itinéraire ?", answer: "Les données d'itinéraire et de cartographie proviennent d'OpenStreetMap et d'OSRM." }, { question: "Sont-ce des estimations ou des prix garantis ?", answer: "Ce sont des estimations — des calculs clairs et fondés sur des règles, à partir de données ouvertes, pas une garantie. Les prix des portails officiels peuvent changer, c'est pourquoi nous vous y renvoyons toujours directement avant l'achat." }] }, { title: "Votre compte", questions: [{ question: "Puis-je utiliser AutoVere sans compte ?", answer: "Oui — le planificateur d'itinéraire, les calculs de coûts et la liste des vignettes fonctionnent entièrement sans connexion. Un compte n'est nécessaire que pour enregistrer vos trajets, véhicules et lieux, et pour les fonctionnalités Pro ou Entreprise." }, { question: "Que m'apporte réellement la création d'un compte ?", answer: "Un endroit où vos trajets, véhicules et arrêts favoris restent enregistrés pour la prochaine fois — et, avec Pro ou Entreprise, les données de recharge en direct, des plans de recharge ajustés à la météo et des profils de véhicule." }] }, { title: "Confidentialité", questions: [{ question: "AutoVere enregistre-t-il mes itinéraires ?", answer: "Seulement si vous êtes connecté et choisissez d'enregistrer un trajet. Les calculs effectués sans compte restent sur votre appareil." }, { question: "Mes données personnelles sont-elles vendues à des tiers ?", answer: "Non. Nous ne vendons aucune donnée et n'utilisons aucun suivi publicitaire tiers, et nous sommes entièrement conformes au RGPD. Consultez notre politique de confidentialité pour tous les détails." }] }] },
  sv: { back: "Tillbaka till resruttplaneraren", title: "Hjälp och FAQ", subtitle: "Tydliga svar på det viktigaste före avresan.", search: "Sök i FAQ...", empty: "Inga matchande frågor hittades.", categories: [{ title: "Vägavgifter och vinjetter", questions: [{ question: "Hur beräknas vägavgifter?", answer: "Vi beräknar vägavgifter utifrån officiella priser, fordonskategori, vägsträcka och säsongsvariationer." }, { question: "Var köper jag officiella vinjetter?", answer: "Vi länkar direkt till officiella statliga utfärdare i varje land för att undvika onödiga avgifter och påslag." }, { question: "Vad gäller för miljödekaler som Crit'Air?", answer: "Vissa europeiska städer kräver egna miljödekaler. Vi visar vilka zoner på din rutt som kan kräva en dekal." }] }, { title: "Elbilar och snabbladdning", questions: [{ question: "Vilka laddnätverk täcks?", answer: "Vi täcker stora öppna europeiska nätverk som Ionity, öppna Tesla Supercharger-stationer, Fastned, EnBW och fler." }, { question: "Hur ofta uppdateras ladddata?", answer: "Ladddatabasen synkroniseras regelbundet med realtidsstatus och öppna databaser." }, { question: "Hur beräknas förbrukning med takbox eller last?", answer: "Kalkylatorn lägger automatiskt till en säkerhetsmarginal och justerar för terräng och ökat luftmotstånd." }] }, { title: "Data och noggrannhet", questions: [{ question: "Varifrån kommer ruttdata?", answer: "Rutt- och kartdata hämtas från OpenStreetMap och OSRM." }, { question: "Är det här uppskattningar eller garanterade priser?", answer: "Det är uppskattningar — transparenta, regelbaserade beräkningar från öppna data, ingen garanti. Priser på officiella portaler kan ändras, så vi länkar alltid dig dit direkt innan du köper." }] }, { title: "Ditt konto", questions: [{ question: "Kan jag använda AutoVere utan konto?", answer: "Ja — resruttplaneraren, kostnadsberäkningarna och vinjettlistan fungerar helt utan inloggning. Ett konto behövs bara för att spara resor, fordon och platser, samt för Pro- eller Företagsfunktioner." }, { question: "Vad ger ett konto mig egentligen?", answer: "En plats där dina resor, fordon och favoritstopp sparas till nästa gång — plus, med Pro eller Företag, laddardata i realtid, väderanpassade laddplaner och fordonsprofiler." }] }, { title: "Integritet", questions: [{ question: "Sparar AutoVere mina rutter?", answer: "Bara om du är inloggad och väljer att spara en resa. Beräkningar du gör utan konto stannar på din egen enhet." }, { question: "Säljs mina personuppgifter till tredje part?", answer: "Nej. Vi säljer inte data eller använder tredjepartsannonsspårning, och vi är fullt GDPR-kompatibla. Se vår integritetspolicy för alla detaljer." }] }] },
  nl: { back: "Terug naar de routeplanner", title: "Hulp en FAQ", subtitle: "Duidelijke antwoorden op wat belangrijk is voordat je vertrekt.", search: "Zoek in de FAQ...", empty: "Geen passende vragen gevonden.", categories: [{ title: "Tol en vignetten", questions: [{ question: "Hoe worden tolkosten berekend?", answer: "We berekenen tol op basis van officiële tarieven, voertuigcategorie, afstand en seizoensvariaties." }] }, { title: "Elektrische auto's en snelladen", questions: [{ question: "Welke laadnetwerken worden ondersteund?", answer: "We ondersteunen grote open Europese netwerken zoals Ionity, open Tesla Supercharger-stations, Fastned en EnBW." }] }, { title: "Gegevens en nauwkeurigheid", questions: [{ question: "Waar komen de routegegevens vandaan?", answer: "Route- en kaartgegevens komen van OpenStreetMap en OSRM." }] }] },
};

const nlFaqCategories: FaqCopy["categories"] = [{ title: "Tol en vignetten", questions: [{ question: "Hoe worden tolkosten berekend?", answer: "We berekenen tol op basis van officiële tarieven, voertuigcategorie, wegafstand en seizoensvariaties." }, { question: "Waar koop ik officiële vignetten?", answer: "We linken rechtstreeks naar de officiële overheidsuitgevers in elk land om onnodige kosten en toeslagen te vermijden." }, { question: "Wat geldt voor milieustickers zoals Crit'Air?", answer: "Sommige Europese steden vereisen een eigen milieusticker. We tonen welke zones op je route er mogelijk een vragen." }] }, { title: "Elektrische auto's en snelladen", questions: [{ question: "Welke laadnetwerken worden ondersteund?", answer: "We ondersteunen grote open Europese netwerken zoals Ionity, open Tesla Supercharger-stations, Fastned, EnBW en meer." }, { question: "Hoe vaak worden laadgegevens bijgewerkt?", answer: "De laadgegevens worden regelmatig gesynchroniseerd met live status en open databases." }, { question: "Hoe wordt het verbruik met een dakkoffer of lading geschat?", answer: "De calculator voegt automatisch een veiligheidsmarge toe en corrigeert voor terrein en extra luchtweerstand." }] }, { title: "Gegevens en nauwkeurigheid", questions: [{ question: "Waar komen de routegegevens vandaan?", answer: "Route- en kaartgegevens komen van OpenStreetMap en OSRM." }, { question: "Zijn dit schattingen of gegarandeerde prijzen?", answer: "Het zijn schattingen — duidelijke, regelgebaseerde berekeningen op basis van open data, geen garantie. Prijzen bij officiële portalen kunnen veranderen, dus we linken je altijd rechtstreeks daarheen voordat je koopt." }] }, { title: "Je account", questions: [{ question: "Kan ik AutoVere gebruiken zonder account?", answer: "Ja — de routeplanner, kostenberekeningen en vignettenchecklist werken volledig zonder in te loggen. Een account heb je alleen nodig om reizen, voertuigen en plekken op te slaan, en voor Pro- of Zakelijke functies." }, { question: "Wat levert een account me eigenlijk op?", answer: "Een plek waar je reizen, voertuigen en favoriete stops bewaard blijven voor de volgende keer — plus, met Pro of Zakelijk, live laaddata, weer-aangepaste laadplannen en voertuigprofielen." }] }, { title: "Privacy", questions: [{ question: "Slaat AutoVere mijn routes op?", answer: "Alleen als je bent ingelogd en ervoor kiest een reis op te slaan. Berekeningen zonder account blijven op je eigen apparaat." }, { question: "Worden mijn persoonsgegevens verkocht aan derden?", answer: "Nee. We verkopen geen gegevens en gebruiken geen tracking door externe adverteerders, en we zijn volledig AVG-compliant. Bekijk ons privacybeleid voor alle details." }] }];
faqCopy.nl.categories = nlFaqCategories;

